import java.util.Map;

public class ClassX {
    /**
     * Validates the token header to ensuring the algorithm is supported.
     * 
     * The function checks if the 'alg' field in the header contains 'HS256'.
     *
     * @param header The map representing the token header.
     * @throws IllegalArgumentException If the 'alg' field is missing or not 'HS256'.
     */
    public void validateTokenHeader(Map<String, String> header) {
        if (header == null) {
            throw new IllegalArgumentException("Token header cannot be null.");
        }

        String algorithm = header.get("alg");

        if (algorithm == null || !algorithm.equals("HS256")) {
            throw new IllegalArgumentException("Unsupported algorithm: " + (algorithm == null ? "null" : algorithm) + ". Only HS256 is supported.");
        }
    }
}
